@Test(timeout = 60000)
public void testReadThroughputLatency() throws Exception {
    final AtomicBoolean threwException = new AtomicBoolean(false);
    Thread t = new Thread() {

        public void run() {
            try {
                BenchReadThroughputLatency.main(new String[] { "--zookeeper", zkUtil.getZooKeeperConnectString(), "--listen", "10" });
            } catch (Throwable t) {
                LOG.error("Error reading", t);
                threwException.set(true);
            }
        }
    };
    t.start();
    Thread.sleep(10000);
    byte[] data = new byte[1024];
    Arrays.fill(data, (byte) 'x');
    long lastLedgerId = 0;
    Assert.assertTrue("Thread should be running", t.isAlive());
    for (int i = 0; i < 10; i++) {
        BookKeeper bk = new BookKeeper(zkUtil.getZooKeeperConnectString());
        LedgerHandle lh = bk.createLedger(BookKeeper.DigestType.CRC32, "benchPasswd".getBytes());
        lastLedgerId = lh.getId();
        try {
            for (int j = 0; j < 100; j++) {
                lh.addEntry(data);
            }
        } finally {
            lh.close();
            bk.close();
        }
    }
    for (int i = 0; i < 60; i++) {
        if (!t.isAlive()) {
            break;
        }
        Thread.sleep(100);
    }
    Assert.assertFalse("Thread should be finished", t.isAlive());
    BenchReadThroughputLatency.main(new String[] { "--zookeeper", zkUtil.getZooKeeperConnectString(), "--ledger", String.valueOf(lastLedgerId) });
}

/**
 * Verify the bookie server exit code. On ZooKeeper exception, should return
 * exit code ZK_REG_FAIL = 4
 */
@Test(timeout = 20000)
public void testExitCodeZK_REG_FAIL() throws Exception {
    File tmpDir = createTempDir("bookie", "test");
    final ServerConfiguration conf = TestBKConfiguration.newServerConfiguration().setZkServers(null).setJournalDirName(tmpDir.getPath()).setLedgerDirNames(new String[] { tmpDir.getPath() });
    // simulating ZooKeeper exception by assigning a closed zk client to bk
    BookieServer bkServer = new BookieServer(conf) {

        protected Bookie newBookie(ServerConfiguration conf) throws IOException, KeeperException, InterruptedException, BookieException {
            MockBookie bookie = new MockBookie(conf);
            bookie.zk = zkc;
            zkc.close();
            return bookie;
        }
    };
    bkServer.start();
    bkServer.join();
    Assert.assertEquals("Failed to return ExitCode.ZK_REG_FAIL", ExitCode.ZK_REG_FAIL, bkServer.getExitCode());
}

