@Test(timeout = 60000)
public void testBookieRecoveryOnInRecoveryLedger() throws Exception {
    int numMsgs = 10;
    // Create the ledgers
    int numLedgers = 1;
    List<LedgerHandle> lhs = createLedgers(numLedgers, 2, 2);
    // Write the entries for the ledgers with dummy values
